SOURCE='\ndef advance(s:readbuf,o:mutbuf,w:mutbuf) -> u32:\n    phase=get(w,0)\n    result=get(w,8)\n    if phase==0:\n        size=metadata_frame(w,0)\n        return pure(o,w,1,P_HTTP_METADATA,H_META_INPUT,size,H_META_RESULT,8388608,PURE_WORK,46137344)\n    if phase==1 or phase==4:\n        if result<128 or result>8388608 or get(w,H_META_RESULT)!=META_OUTPUT_MAGIC:\n            return 0\n        size=get(w,H_META_RESULT+32)\n        if size!=result-128:\n            return 0\n        if get(w,H_META_RESULT+8)!=0:\n            return respond(w,get(w,H_META_RESULT+8),H_META_RESULT+128,size,get(w,H_META_RESULT+24),0)\n        put(w,H_LEGACY,get(w,H_META_RESULT+16))\n        put(w,H_CLIENT_CAP_SPAN,get(w,H_META_RESULT+64))\n        if phase==4:\n            return admitted(o,w)\n        if get(w,H_LEGACY)==0:\n            put(w,H_S_FOUND,0)\n            return standard(o,w)\n        row=get(w,H_META_RESULT+48)\n        if row==0:\n            put(w,H_S_FOUND,0)\n            if get(w,CR_ROUTE)!=1:\n                return missing_session(w)\n            return standard(o,w)\n        if row>get(w,H_HEADER_DESC+56):\n            return 0\n        row=H_HEADER_DESC+128+(row-1)*32\n        return lookup_session(w,H_HEADER+get(w,row+16),get(w,row+24),HTTP_POST,3)\n    if phase==3:\n        if get(w,H_S_FOUND)==0:\n            if get(w,CR_ROUTE)==3:\n                return respond(w,202,H_IO,0,0,0)\n            end=text_not_found(w,H_OUTPUT)\n            return respond(w,404,H_OUTPUT,end-H_OUTPUT,0,0)\n        if get(w,CR_ROUTE)==2:\n            put(w,CR_SESSION,get(w,H_S_CURRENT))\n            return enter(w,HTTP_EVENTS,200)\n        if get(w,CR_ROUTE)==3:\n            put(w,H_DELETE_CONN,get(w,H_CURRENT))\n            put(w,H_DELETE_PENDING,1)\n            return save_conn(w,HTTP_DELIVERY,900)\n        return standard(o,w)\n\n    if phase==60:\n        if result==0 or result>8388608:\n            return 0\n        put(w,H_ID_N,result)\n        put(w,H_ID_USED,0)\n        return sha(o,w,61,0,1)\n    if phase==61 or phase==62:\n        if result!=0:\n            return 0\n        used=get(w,H_ID_USED)\n        size=get(w,H_ID_N)-used\n        if size==0:\n            return sha(o,w,63,2,1)\n        if size>65536:\n            size=65536\n        copy_state(w,PURE_OUTPUT+used,SHA_INPUT+1,size)\n        put(w,H_ID_USED,used+size)\n        return sha(o,w,62,1,size+1)\n    if phase==63:\n        if result!=32:\n            return 0\n        copy_state(w,SHA_OUTPUT,CR_ID_KEY,32)\n        put(w,CR_ID_VALID,1)\n        return dispatch_admitted(w)\n    if phase==55:\n        return load_conn(w,get(w,H_CANCEL_CONN),HTTP_POST,56)\n    if phase==56:\n        return respond(w,202,H_IO,0,0,0)\n    if phase==50:\n        copy_state(w,H_REQUEST_DESCRIPTOR,CR_SDK,160)\n        put(w,CR_SESSION,get(w,H_S_CURRENT))\n        copy_state(w,SR_UUID,CR_UUID,36)\n        kind=get(w,H_REQUEST_DESCRIPTOR+8)\n        role=get(w,H_REQUEST_DESCRIPTOR+16)\n        put(w,H_REQUEST_KIND,kind)\n        flags=get(w,CR_FLAGS)&255\n        if get(w,H_LEGACY)==0:\n            flags=flags|32\n        if kind==1 and role==1:\n            flags=flags|2\n        put(w,CR_FLAGS,flags)\n        slot=allocate_task(w)\n        if slot==NONE:\n            put(w,CR_STATUS,6)\n            return save_conn(w,HTTP_IO,3)\n        row=task_row(slot)\n        register_request(w,row,kind)\n        if kind==2 and role==9:\n            cancellation_route(w,row)\n        put(w,row+56,get(w,CR_BODY_FD))\n        put(w,row+64,get(w,CR_BODY_N))\n        put(w,CR_BODY_FD,NONE)\n        put(w,row+72,1)\n        put(w,row+80,kind)\n        put(w,row+128,get(w,H_REQUEST_DESCRIPTOR+24))\n        put(w,row+136,get(w,H_REQUEST_DESCRIPTOR+64))\n        put(w,row+144,get(w,H_REQUEST_DESCRIPTOR+72))\n        put(w,row+152,role)\n        put(w,row+160,flags)\n        put(w,row+168,get(w,H_REQUEST_DESCRIPTOR+104))\n        stream=get(w,SR_NEXT_STREAM)\n        if kind==1:\n            if role==1:\n                stream=0\n            else:\n                if stream==NONE:\n                    return 0\n                put(w,SR_NEXT_STREAM,stream+1)\n        put(w,CR_STREAM_ID,stream)\n        put(w,row+32,stream)\n        put(w,SR_PENDING,get(w,SR_PENDING)+1)\n        put(w,SR_LAST_NS,get(w,H_NOW))\n        put(w,CR_STATUS,5)\n        return save_session(w,HTTP_POST,51)\n    if phase==51:\n        return save_conn(w,HTTP_POST,52)\n    if phase==52:\n        put(w,H_IO,4)\n        put(w,H_IO+4,(get(w,H_S_CURRENT)+1)*8+3)\n        return call(o,w,53,233,get(w,H_EPOLL),3,get(w,SR_INPUT_FD),H_IO,0,0,192)\n    if phase==53:\n        if failed(result):\n            return enter(w,HTTP_DELIVERY,900)\n        if get(w,H_REQUEST_KIND)!=1:\n            row=task_row(get(w,CR_TASK_SLOT))\n            target=get(w,row+232)\n            put(w,row+24,NONE)\n            put(w,CR_TASK_SLOT,NONE)\n            put(w,CR_TASK_GENERATION,0)\n            if target!=0:\n                put(w,H_CANCEL_CONN,get(w,H_CURRENT))\n                put(w,H_CANCEL_SLOT,target-1)\n                return save_conn(w,HTTP_EVENTS,400)\n            return respond(w,202,H_IO,0,0,0)\n        if get(w,H_LEGACY)==1:\n            return enter(w,HTTP_EVENTS,0)\n        return enter(w,HTTP_IO,3)\n    return 0\n\ndef metadata_frame(w:mutbuf,mode:u64) -> u64:\n    put(w,H_META_INPUT,META_INPUT_MAGIC)\n    put(w,H_META_INPUT+8,mode)\n    put(w,H_META_INPUT+16,get(w,CR_HEADER_N))\n    dn=128+get(w,H_HEADER_DESC+56)*32\n    put(w,H_META_INPUT+24,dn)\n    body=choose(get(w,CR_ROUTE)==1,get(w,CR_BODY_N),0)\n    sdk=choose(get(w,CR_ROUTE)==1,160,0)\n    put(w,H_META_INPUT+32,body)\n    put(w,H_META_INPUT+40,sdk)\n    put(w,H_META_INPUT+48,get(w,S_CATALOG+8))\n    put(w,H_META_INPUT+56,0)\n    at=copy_state(w,H_HEADER,H_META_INPUT+64,get(w,CR_HEADER_N))\n    at=copy_state(w,H_HEADER_DESC,at,dn)\n    at=copy_state(w,H_INPUT,at,body)\n    at=copy_state(w,H_REQUEST_DESCRIPTOR,at,sdk)\n    at=cp(w,S_CATALOG,at)\n    return at-H_META_INPUT\n\ndef standard(o:mutbuf,w:mutbuf) -> u32:\n    size=metadata_frame(w,1)\n    return pure(o,w,4,P_HTTP_METADATA,H_META_INPUT,size,H_META_RESULT,8388608,PURE_WORK,46137344)\n\ndef dispatch_admitted(w:mutbuf) -> u32:\n    if get(w,H_S_FOUND)!=0 and get(w,H_LEGACY)==1:\n        put(w,CR_SESSION,get(w,H_S_CURRENT))\n        return enter(w,HTTP_POST,50)\n    if get(w,H_LEGACY)==1:\n        if get(w,H_REQUEST_DESCRIPTOR+8)!=1 or get(w,H_REQUEST_DESCRIPTOR+16)!=1:\n            return missing_session(w)\n    return enter(w,HTTP_SESSION,0)\n\ndef missing_session(w:mutbuf) -> u32:\n    end=text_required(w,H_OUTPUT)\n    return respond(w,400,H_OUTPUT,end-H_OUTPUT,0,0)\n\ndef admitted(o:mutbuf,w:mutbuf) -> u32:\n    put(w,CR_ID_VALID,0)\n    kind=get(w,H_REQUEST_DESCRIPTOR+8)\n    span=0\n    if kind==1:\n        span=get(w,H_REQUEST_DESCRIPTOR+24)\n    elif kind==2 and get(w,H_REQUEST_DESCRIPTOR+16)==9:\n        span=get(w,H_REQUEST_DESCRIPTOR+120)\n    if span==0:\n        return dispatch_admitted(w)\n    at=(span&16777215)-1\n    end=(span>>24)&16777215\n    if end<at or end>get(w,CR_BODY_N):\n        return 0\n    return pure(o,w,60,P_SDK,H_INPUT+at,end-at,PURE_OUTPUT,8389120,PURE_WORK,32768)\n\ndef register_request(w:mutbuf,row:u64,kind:u64) -> u64:\n    put(w,row+224,0)\n    put(w,row+216,get(w,CR_ID_VALID))\n    if get(w,CR_ID_VALID)==0:\n        return 0\n    copy_state(w,CR_ID_KEY,row+184,32)\n    if kind!=1:\n        return 0\n    index=0\n    while index<32:\n        previous=task_row(index)\n        if previous!=row and get(w,previous)==1 and get(w,previous+16)==get(w,H_S_CURRENT) and get(w,previous+216)==1 and equal(w,previous+184,row+184,32):\n            put(w,previous+176,0)\n        index=index+1\n    put(w,row+176,1)\n    return 0\n\ndef cancellation_route(w:mutbuf,row:u64) -> u64:\n    put(w,H_CANCEL_SLOT,NONE)\n    if get(w,CR_ID_VALID)==0:\n        return 0\n    index=0\n    while index<32:\n        target=task_row(index)\n        if target!=row and get(w,target)==1 and get(w,target+16)==get(w,H_S_CURRENT) and get(w,target+176)==1 and get(w,target+216)==1 and equal(w,target+184,CR_ID_KEY,32):\n            put(w,target+176,0)\n            put(w,target+224,1)\n            put(w,H_CANCEL_SLOT,index)\n            put(w,H_CANCEL_GENERATION,get(w,target+8))\n            put(w,row+232,index+1)\n            put(w,row+240,get(w,target+8))\n            return 0\n        index=index+1\n    return 0\n'
